WITH deduped AS (SELECT id, store_id, quantity, last_restock FROM (SELECT *, RANK() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC NULLS LAST) AS latest_rank FROM inventory) t WHERE latest_rank = 1) SELECT CASE WHEN quantity >= 186 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, ROUND(AVG(quantity), 2) AS avg_quantity FROM deduped GROUP BY CASE WHEN quantity >= 186 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_quantity DESC
